package com.dormrepair.file;
import com.dormrepair.common.enums.*;import com.dormrepair.common.exception.BusinessException;import com.dormrepair.config.*;import com.dormrepair.domain.entity.*;import com.dormrepair.domain.mapper.*;import com.dormrepair.file.service.*;import com.dormrepair.security.model.LoginUser;import io.minio.MinioClient;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockMultipartFile;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.transaction.support.TransactionTemplate;import java.time.Duration;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class FileServiceTest {SysFileMapper files;RepairOrderFileMapper orderFiles;RepairProcessFileMapper processFiles;RepairReworkFileMapper reworkFiles;MinioClient minio;FileServiceImpl service;
 @BeforeEach void setup(){files=mock(SysFileMapper.class);orderFiles=mock(RepairOrderFileMapper.class);processFiles=mock(RepairProcessFileMapper.class);reworkFiles=mock(RepairReworkFileMapper.class);minio=mock(MinioClient.class);service=new FileServiceImpl(minio,new MinioProperties("http://localhost:9000","a","b","repair-files",1800,false),new FileUploadProperties(10,20,Set.of("jpg"),Set.of("mp4"),Set.of("image/jpeg"),Set.of("video/mp4"),Duration.ofHours(24),100),files,orderFiles,processFiles,reworkFiles,mock(TransactionTemplate.class));login(UserRoleEnum.STUDENT);}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void rejectsExtensionMimeMismatch(){MockMultipartFile f=new MockMultipartFile("file","x.jpg","video/mp4",new byte[]{1});assertThatThrownBy(()->service.upload(f,FileBizTypeEnum.REPAIR)).isInstanceOf(BusinessException.class).extracting("code").isEqualTo(18003);}
 @Test void rejectsRoleMismatch(){MockMultipartFile f=new MockMultipartFile("file","x.jpg","image/jpeg",new byte[]{1});assertThatThrownBy(()->service.upload(f,FileBizTypeEnum.PROCESS)).isInstanceOf(BusinessException.class).extracting("code").isEqualTo(10003);}
 @Test void bindingDeduplicatesIdsAndPreservesClientOrder(){when(files.selectByIdForUpdate(2L)).thenReturn(file(2L,1L,"REPAIR"));when(files.selectByIdForUpdate(1L)).thenReturn(file(1L,1L,"REPAIR"));service.bindOrderFiles(9L,List.of(2L,1L,2L),1L);verify(orderFiles,times(2)).insert(any());verify(orderFiles).insert(argThat(r->r.getFileId()==2L&&r.getSortNo()==0));verify(orderFiles).insert(argThat(r->r.getFileId()==1L&&r.getSortNo()==1));}
 @Test void bindingRejectsAnotherUsersFile(){when(files.selectByIdForUpdate(2L)).thenReturn(file(2L,99L,"REPAIR"));assertThatThrownBy(()->service.bindOrderFiles(9L,List.of(2L),1L)).isInstanceOf(BusinessException.class).extracting("code").isEqualTo(18006);verifyNoInteractions(orderFiles);}
 private SysFile file(Long id,Long user,String biz){SysFile f=new SysFile();f.setId(id);f.setCreateBy(user);f.setBizType(biz);f.setFileType("IMAGE");f.setStatus(1);f.setDeleted(0);return f;}
 private void login(UserRoleEnum r){LoginUser u=new LoginUser(1L,"u","u",r);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of()));}}
